    )
    .eq('studio_id', auth.studioId)
    .order('created_at', { ascending: false })
    .range(offset, offset + limit - 1)

  if (error) {
    logger.error({ err: error, studioId: auth.studioId }, 'invoices fetch failed')
    return NextResponse.json({ error: 'failed to load invoices' }, { status: 500 })
  }

  return NextResponse.json({
    invoices: data ?? [],
    total: count ?? 0,
    page,
    limit,
    hasMore: ((count ?? 0) > offset + limit),
  })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const CreateRefundSchema = z.object({
  payment_id: z.string().uuid(),
  amount_cents: z.number().int().positive(),
  reason: z.enum(['client_request', 'error', 'duplicate', 'other']),
  notes: z.string().max(500).optional(),
})

/**
 * POST /api/billing/refund-requests — Create a refund request.
 * GET  /api/billing/refund-requests — List refund requests for the studio.
 */
export async function POST(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  // Only owner or admin may request refunds
  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'insufficient permissions' }, { status: 403 })
  }

  const body = CreateRefundSchema.safeParse(await req.json().catch(() => ({})))
  if (!body.success) {
    return NextResponse.json({ error: body.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()

  // Verify payment belongs to this studio
  const { data: payment } = await supabase
    .from('payments')
    .select('id, dodo_payment_id, amount_cents, status')
    .eq('id', body.data.payment_id)
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!payment) {
    return NextResponse.json({ error: 'payment not found' }, { status: 404 })
  }

  if (payment.status !== 'succeeded') {
    return NextResponse.json({ error: 'can only refund succeeded payments' }, { status: 409 })
  }

  if (body.data.amount_cents > payment.amount_cents) {
    return NextResponse.json({ error: 'refund amount exceeds payment amount' }, { status: 422 })
  }

  const { data: refundReq, error } = await supabase
    .from('refund_requests')
    .insert({
      studio_id: auth.studioId,
      payment_id: payment.id,
      dodo_payment_id: payment.dodo_payment_id,
      amount_cents: body.data.amount_cents,
      reason: body.data.reason,
      notes: body.data.notes ?? null,
      status: 'pending',
      requested_by: auth.user.authId,
    })
    .select()
    .single()

  if (error) {
    logger.error({ err: error, studioId: auth.studioId }, 'refund request insert failed')
    return NextResponse.json({ error: 'failed to create refund request' }, { status: 500 })
  }

  await logAuditAction(
    auth.user.authId,
    'billing.refund.requested',
    { type: 'payment', id: payment.id },
    { amountCents: body.data.amount_cents, reason: body.data.reason },
    auth.studioId,
  )

  return NextResponse.json({ refundRequest: refundReq }, { status: 201 })
}

