  isAnnual: boolean
  currentTier: PlanTier
  isLoadingCheckout: boolean
  onUpgrade: (tier: PlanTier) => void
  onDowngrade: (tier: PlanTier) => void
}

const TIER_ORDER: Record<PlanTier, number> = { solo: 0, studio: 1, pro: 2, enterprise: 3 }

export function PlanCard({ plan, isAnnual, currentTier, isLoadingCheckout, onUpgrade, onDowngrade }: PlanCardProps) {
  const isCurrent = plan.tier === currentTier
  const isHigher = TIER_ORDER[plan.tier] > TIER_ORDER[currentTier]
  const isEnterprise = plan.tier === 'enterprise'

  const features = Array.isArray(plan.features) ? (plan.features as string[]) : []

  return (
    <div
      className={cn(
        'rounded-xl border border-border/60 p-5 flex flex-col gap-4',
        'transition-all duration-150 ease-out',
        isCurrent && 'plan-card-current',
        isEnterprise && !isCurrent && 'plan-card-enterprise',
        !isCurrent && 'hover:border-border hover:shadow-sm',
      )}
    >
      {/* Header */}
      <div>
        <div className="flex items-center justify-between">
          <span className="text-xs font-semibold uppercase tracking-widest text-muted-foreground">
            {plan.tier}
          </span>
          {isCurrent && (
            <span className="text-[10px] font-semibold rounded-full px-2 py-0.5 bg-[oklch(62%_0.24_292/0.15)] text-[oklch(72%_0.18_292)] border border-[oklch(62%_0.24_292/0.3)]">
              Current
            </span>
          )}
        </div>
        <div className="mt-2 flex items-baseline gap-1">
          <span className="text-3xl font-bold tabular-nums">
            {formatCurrency(plan.price_cents, plan.currency)}
          </span>
          <span className="text-sm text-muted-foreground">
            / {isAnnual ? 'mo, billed annually' : 'month'}
          </span>
        </div>
        {plan.price_cents === 0 && (
          <p className="text-xs text-muted-foreground mt-1">Free forever</p>
        )}
      </div>

      <Separator />

      {/* Feature list */}
      <ul className="space-y-2 flex-1">
        {features.map((f) => (
          <li key={f} className="flex items-center gap-2 text-xs text-muted-foreground">
            <Check className="h-3.5 w-3.5 shrink-0 text-[oklch(58%_0.18_145)]" />
            {f}
          </li>
        ))}
        <li className="flex items-center gap-2 text-xs text-muted-foreground">
          <Users className="h-3.5 w-3.5 shrink-0" />
          {plan.max_artists !== null && plan.max_artists !== undefined
            ? `Up to ${plan.max_artists} artist${plan.max_artists === 1 ? '' : 's'}`
            : 'Unlimited artists'}
        </li>
        {plan.sms_monthly_quota !== null && plan.sms_monthly_quota !== undefined && plan.sms_monthly_quota > 0 && (
          <li className="flex items-center gap-2 text-xs text-muted-foreground">
            <MessageSquare className="h-3.5 w-3.5 shrink-0" />
            {plan.sms_monthly_quota.toLocaleString()} SMS / month
          </li>
        )}
      </ul>

      {/* CTA */}
      {isCurrent ? (
        <Button disabled className="w-full" size="sm">
          Current plan
        </Button>
      ) : isEnterprise ? (
        <Button variant="outline" className="w-full" size="sm" asChild>
          <a href="mailto:hello@inkos.app">Contact sales</a>
        </Button>
      ) : isHigher ? (
        <Button
          className="w-full"
          size="sm"
          onClick={() => onUpgrade(plan.tier)}
          disabled={isLoadingCheckout}
        >
          {isLoadingCheckout ? (
            <>
              <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
              Redirecting...
            </>
          ) : (
            `Upgrade to ${plan.tier.charAt(0).toUpperCase() + plan.tier.slice(1)}`
          )}
        </Button>
      ) : (
        <Button
          variant="outline"
          className="w-full"
          size="sm"
          onClick={() => onDowngrade(plan.tier)}
          disabled={isLoadingCheckout}
        >
          Downgrade
        </Button>
      )}
    </div>
  )
}

