import { useState } from 'react'
import { Switch } from '@/components/ui/switch'
import { Skeleton } from '@/components/ui/skeleton'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { X } from 'lucide-react'
import { cn } from '@/lib/utils'
import { PlanCard } from './PlanCard'
import { toast } from 'sonner'
import type { StudioSubscriptionRpc } from '@/lib/billing/schemas'
import type { PlanTier } from '@/lib/dodo/client'

interface PlanSelectorProps {
  plans: StudioSubscriptionRpc['plan'][]
  subscription: StudioSubscriptionRpc['subscription']
}

export function PlanSelector({ plans, subscription }: PlanSelectorProps) {
  const [isAnnual, setIsAnnual] = useState(subscription.billing_cycle === 'annual')
  const [checkoutLoading, setCheckoutLoading] = useState<PlanTier | null>(null)
  const [downgradeTarget, setDowngradeTarget] = useState<StudioSubscriptionRpc['plan'] | null>(null)

  const currentCycle = isAnnual ? 'annual' : 'monthly'
  const filteredPlans = plans.filter((p) => p.billing_cycle === currentCycle)

  async function startCheckout(tier: PlanTier, billingCycle: 'monthly' | 'annual') {
    setCheckoutLoading(tier)
    try {
      const res = await fetch('/api/billing/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tier, billingCycle }),
      })
      const json = await res.json() as { checkoutUrl?: string; error?: string }
      if (!res.ok || !json.checkoutUrl) {
        throw new Error(json.error ?? 'Failed to start checkout')
      }
      window.location.href = json.checkoutUrl
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Could not start checkout. Try again.')
      setCheckoutLoading(null)
    }
  }

  function handleUpgrade(tier: PlanTier) {
    void startCheckout(tier, currentCycle)
  }

  function handleDowngrade(plan: StudioSubscriptionRpc['plan']) {
    setDowngradeTarget(plan)
  }

  async function confirmDowngrade() {
    if (!downgradeTarget) return
    setDowngradeTarget(null)
    await startCheckout(downgradeTarget.tier, currentCycle)
  }

  const downgradeFeatureDiff = (() => {
    if (!downgradeTarget) return []
    const currentFeatures = plans.find((p) => p.tier === subscription.plan_tier && p.billing_cycle === currentCycle)?.features
    const newFeatures = downgradeTarget.features
    if (!Array.isArray(currentFeatures) || !Array.isArray(newFeatures)) return []
    return (currentFeatures as string[]).filter((f) => !(newFeatures as string[]).includes(f))
  })()

  return (
    <div className="space-y-4">
      {/* Annual/Monthly toggle */}
      <div className="flex items-center justify-center gap-3">
        <span className={cn('text-sm font-medium', !isAnnual && 'text-foreground', isAnnual && 'text-muted-foreground')}>
          Monthly
        </span>
        <Switch checked={isAnnual} onCheckedChange={setIsAnnual} />
        <span className={cn('text-sm font-medium', isAnnual && 'text-foreground', !isAnnual && 'text-muted-foreground')}>
          Annual
        </span>
        {isAnnual && (
          <span className="inline-flex items-center rounded-full bg-[oklch(58%_0.18_145/0.15)] text-[oklch(65%_0.14_145)] border border-[oklch(58%_0.18_145/0.3)] px-2 py-0.5 text-xs font-semibold">
            Save 20%
          </span>
        )}
      </div>

      {/* Plan cards grid */}
      <div className="mt-6 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {filteredPlans.length > 0
          ? filteredPlans.map((plan) => (
              <PlanCard
                key={plan.tier}
                plan={plan}
                isAnnual={isAnnual}
                currentTier={subscription.plan_tier}
                isLoadingCheckout={checkoutLoading === plan.tier}
                onUpgrade={handleUpgrade}
                onDowngrade={() => handleDowngrade(plan)}
              />
            ))
          : Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} className="h-64 rounded-xl" />
            ))}
      </div>

      {/* Downgrade confirmation */}
      <AlertDialog open={!!downgradeTarget} onOpenChange={(open) => !open && setDowngradeTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              Downgrade to {downgradeTarget?.tier.charAt(0).toUpperCase()}{downgradeTarget?.tier.slice(1)}?
            </AlertDialogTitle>
            <AlertDialogDescription className="space-y-3">
              <span className="block">
                Your {subscription.plan_tier} features stay active until{' '}
                {subscription.current_period_end
                  ? new Date(subscription.current_period_end).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })
                  : 'the end of your billing period'}
                . After that, you&apos;ll lose access to:
              </span>
              {downgradeFeatureDiff.length > 0 && (
                <ul className="space-y-1">
                  {downgradeFeatureDiff.map((f) => (
                    <li key={f} className="flex items-center gap-2 text-xs text-destructive/80">
                      <X className="h-3 w-3 shrink-0" />
                      {f}
                    </li>
                  ))}
                </ul>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep current plan</AlertDialogCancel>
            <AlertDialogAction
              onClick={(e) => { e.preventDefault(); void confirmDowngrade() }}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Confirm downgrade
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

'use client'

import { useState } from 'react'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { ExternalLink, FileText } from 'lucide-react'
import { cn } from '@/lib/utils'
import { formatCurrency } from '@/lib/utils'

interface Invoice {
  id: string
  dodo_invoice_id: string
  amount_cents: number
  currency: string
  status: 'draft' | 'open' | 'paid' | 'uncollectible' | 'void' | 'refunded'
  period_start: string | null
  period_end: string | null
  paid_at: string | null
  pdf_url: string | null
  hosted_url: string | null
  created_at: string
}

interface InvoiceTableProps {
  invoices: Invoice[]
  isLoading?: boolean
}

const STATUS_LABELS: Record<Invoice['status'], string> = {
  draft:         'Draft',
  open:          'Open',
  paid:          'Paid',
  uncollectible: 'Uncollectible',
  void:          'Void',
  refunded:      'Refunded',
}

function formatDate(iso: string | null) {
  if (!iso) return '—'
  return new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
}

export function InvoiceTable({ invoices, isLoading }: InvoiceTableProps) {
  const [page, setPage] = useState(1)
  const perPage = 5
  const total = invoices.length
  const paged = invoices.slice((page - 1) * perPage, page * perPage)

  if (isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 4 }).map((_, i) => (
          <Skeleton key={i} className="h-12 w-full rounded-lg" />
        ))}
      </div>
    )
  }

  if (invoices.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 text-center">
        <FileText className="h-8 w-8 text-muted-foreground/40 mb-3" />
        <p className="text-sm font-medium text-muted-foreground">No invoices yet</p>
        <p className="text-xs text-muted-foreground mt-1">Invoices appear here after your first billing cycle.</p>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="rounded-lg border border-border/60 overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              <TableHead className="text-xs font-medium text-muted-foreground">Invoice</TableHead>
              <TableHead className="text-xs font-medium text-muted-foreground">Period</TableHead>
              <TableHead className="text-xs font-medium text-muted-foreground">Status</TableHead>
              <TableHead className="text-xs font-medium text-muted-foreground text-right">Amount</TableHead>
              <TableHead className="w-16" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {paged.map((inv) => (
              <TableRow key={inv.id} className="hover:bg-muted/30">
                <TableCell className="font-mono text-xs text-muted-foreground">
                  #{inv.dodo_invoice_id.slice(-8).toUpperCase()}
                </TableCell>
                <TableCell className="text-sm">
                  {formatDate(inv.period_start)}
                  {inv.period_start && inv.period_end && ' – '}
                  {formatDate(inv.period_end)}
                </TableCell>
                <TableCell>
                  <span className={cn('inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium border', `badge-inv-${inv.status}`)}>
                    {STATUS_LABELS[inv.status]}
                  </span>
                </TableCell>
                <TableCell className="text-right font-semibold tabular-nums text-sm">
                  {formatCurrency(inv.amount_cents, inv.currency)}
                </TableCell>
                <TableCell>
                  <div className="flex items-center gap-1 justify-end">
                    {inv.pdf_url && (
                      <a href={inv.pdf_url} target="_blank" rel="noopener noreferrer">
                        <Button variant="ghost" size="icon" className="h-7 w-7">
                          <FileText className="h-3.5 w-3.5" />
                          <span className="sr-only">Download PDF</span>
                        </Button>
                      </a>
                    )}
                    {inv.hosted_url && (
                      <a href={inv.hosted_url} target="_blank" rel="noopener noreferrer">
                        <Button variant="ghost" size="icon" className="h-7 w-7">
                          <ExternalLink className="h-3.5 w-3.5" />
                          <span className="sr-only">View invoice</span>
                        </Button>
                      </a>
                    )}
                  </div>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>

      {total > perPage && (
        <div className="flex items-center justify-between text-xs text-muted-foreground">
          <span>
            Showing {(page - 1) * perPage + 1}–{Math.min(page * perPage, total)} of {total}
          </span>
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              disabled={page === 1}
            >
              Previous
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => p + 1)}
              disabled={page * perPage >= total}
            >
              Next
            </Button>
          </div>
        </div>
      )}
    </div>
  )
}

