}

interface UpgradeModalContextValue {
  openUpgradeModal: (opts: { requiredPlan: PlanTier; feature: string; description?: string }) => void
}

const UpgradeModalContext = createContext<UpgradeModalContextValue | null>(null)

export function UpgradeModalProvider({ children }: { children: React.ReactNode }) {
  const [state, setState] = useState<UpgradeModalState>({
    open: false,
    requiredPlan: 'studio',
    feature: '',
  })

  const openUpgradeModal = useCallback(
    (opts: { requiredPlan: PlanTier; feature: string; description?: string }) => {
      setState({ ...opts, open: true })
    },
    []
  )

  async function handleUpgrade() {
    try {
      const res = await fetch('/api/billing/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tier: state.requiredPlan, billingCycle: 'monthly' }),
      })
      const json = await res.json() as { checkoutUrl?: string }
      if (json.checkoutUrl) {
        window.location.href = json.checkoutUrl
      }
    } catch {
      // Silent — user can navigate to /settings/billing to upgrade
    }
  }

  return (
    <UpgradeModalContext.Provider value={{ openUpgradeModal }}>
      {children}
      <UpgradeGateModal
        open={state.open}
        onOpenChange={(open) => setState((s) => ({ ...s, open }))}
        requiredPlan={state.requiredPlan}
        feature={state.feature}
        description={state.description}
        onUpgrade={() => void handleUpgrade()}
      />
    </UpgradeModalContext.Provider>
  )
}

export function useUpgradeModal() {
  const ctx = useContext(UpgradeModalContext)
  if (!ctx) throw new Error('useUpgradeModal must be used inside UpgradeModalProvider')
  return ctx
}

