interface RefundModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  paymentId: string
  amountCents: number
  currency: string
  label?: string
  onSuccess?: () => void
}

type RefundReason = 'client_request' | 'error' | 'duplicate' | 'other'

const REASON_LABELS: Record<RefundReason, string> = {
  client_request: 'Client request',
  error:          'Error / mistake',
  duplicate:      'Duplicate charge',
  other:          'Other',
}

export function RefundModal({
  open,
  onOpenChange,
  paymentId,
  amountCents,
  currency,
  label,
  onSuccess,
}: RefundModalProps) {
  const [reason, setReason] = useState<RefundReason>('client_request')
  const [notes, setNotes] = useState('')
  const [isPending, setIsPending] = useState(false)

  async function handleSubmit() {
    setIsPending(true)
    try {
      const res = await fetch('/api/billing/refund-requests', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ payment_id: paymentId, amount_cents: amountCents, reason, notes: notes || undefined }),
      })
      const json = await res.json() as { error?: string }
      if (!res.ok) throw new Error(json.error ?? 'Failed to submit refund request')
      toast.success('Refund request submitted')
      onOpenChange(false)
      setNotes('')
      onSuccess?.()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to submit refund')
    } finally {
      setIsPending(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Request refund</DialogTitle>
          <DialogDescription>
            Submit a refund request for{' '}
            <span className="font-semibold tabular-nums">{formatCurrency(amountCents, currency)}</span>
            {label ? ` — ${label}` : ''}. Refunds are processed within 3–5 business days.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          <div className="space-y-2">
            <Label htmlFor="reason">Reason</Label>
            <Select value={reason} onValueChange={(v) => setReason(v as RefundReason)}>
              <SelectTrigger id="reason">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {Object.entries(REASON_LABELS).map(([k, v]) => (
                  <SelectItem key={k} value={k}>{v}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Notes <span className="text-muted-foreground text-xs">(optional)</span></Label>
            <Textarea
              id="notes"
              placeholder="Provide additional context..."
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              maxLength={500}
              rows={3}
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isPending}>
            Cancel
          </Button>
          <Button onClick={() => void handleSubmit()} disabled={isPending}>
            {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Submit request
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { cn } from '@/lib/utils'
import { Clock, CheckCircle2, XCircle, RotateCcw } from 'lucide-react'

type RefundStatus = 'pending' | 'approved' | 'rejected' | 'processed'

interface RefundStatusTimelineProps {
  status: RefundStatus
  requestedAt: string
  processedAt?: string | null
  rejectionReason?: string | null
}

const STEPS: Array<{ key: RefundStatus | 'approved'; label: string }> = [
  { key: 'pending',   label: 'Request submitted' },
  { key: 'approved',  label: 'Under review' },
  { key: 'processed', label: 'Refund processed' },
]

function stepIndex(status: RefundStatus): number {
  switch (status) {
    case 'pending':   return 0
    case 'approved':  return 1
    case 'processed': return 2
    case 'rejected':  return 1
    default:          return 0
  }
}

export function RefundStatusTimeline({ status, requestedAt, processedAt, rejectionReason }: RefundStatusTimelineProps) {
  const currentIdx = stepIndex(status)
  const isRejected = status === 'rejected'

  return (
    <div className="space-y-4">
      <div className="flex items-start gap-0">
        {STEPS.map((step, i) => {
          const isDone = i < currentIdx || status === 'processed'
          const isCurrent = i === currentIdx && !isRejected
          const isLast = i === STEPS.length - 1

          return (
            <div key={step.key} className="flex flex-col items-center flex-1 relative">
              {/* Connector line */}
              {!isLast && (
                <div
                  className={cn(
                    'absolute top-4 left-1/2 w-full h-0.5 transition-colors',
                    isDone ? 'bg-[oklch(58%_0.18_145)]' : 'bg-border/60'
                  )}
                />
              )}

              {/* Dot */}
              <div
                className={cn(
                  'relative z-10 flex items-center justify-center h-8 w-8 rounded-full border-2 transition-colors',
                  isDone
                    ? 'bg-[oklch(58%_0.18_145)] border-[oklch(58%_0.18_145)]'
                    : isCurrent
                      ? 'bg-background border-[oklch(62%_0.24_292)] text-[oklch(72%_0.18_292)]'
                      : isRejected && i === 1
                        ? 'bg-destructive/10 border-destructive'
                        : 'bg-background border-border/60'
                )}
              >
                {isDone ? (
                  <CheckCircle2 className="h-4 w-4 text-white" />
                ) : isCurrent ? (
                  <Clock className="h-3.5 w-3.5" />
                ) : isRejected && i === 1 ? (
                  <XCircle className="h-4 w-4 text-destructive" />
                ) : status === 'processed' && i === 2 ? (
                  <RotateCcw className="h-3.5 w-3.5 text-white" />
                ) : null}
              </div>

              {/* Label */}
              <div className="mt-2 text-center px-1">
                <p
                  className={cn(
                    'text-xs font-medium',
                    isDone || isCurrent ? 'text-foreground' : 'text-muted-foreground'
                  )}
                >
                  {isRejected && i === 1 ? 'Rejected' : step.label}
                </p>
                {i === 0 && (
                  <p className="text-[10px] text-muted-foreground mt-0.5 tabular-nums">
                    {new Date(requestedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                  </p>
                )}
                {i === 2 && processedAt && status === 'processed' && (
                  <p className="text-[10px] text-muted-foreground mt-0.5 tabular-nums">
                    {new Date(processedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                  </p>
                )}
              </div>
            </div>
          )
        })}
      </div>

      {isRejected && rejectionReason && (
        <div className="rounded-lg bg-destructive/5 border border-destructive/20 p-3">
          <p className="text-xs text-destructive font-medium">Rejection reason</p>
          <p className="text-xs text-muted-foreground mt-1">{rejectionReason}</p>
        </div>
      )}
    </div>
  )
}

