  disabled?: boolean
}

export function CollectBalanceButton({ bookingId, balanceCents, currency = 'USD', disabled }: CollectBalanceButtonProps) {
  const [isLoading, setIsLoading] = useState(false)

  async function handleCollect() {
    setIsLoading(true)
    try {
      const res = await fetch(`/api/bookings/${bookingId}/collect-balance`, { method: 'POST' })
      const json = await res.json() as { checkoutUrl?: string; error?: string }
      if (!res.ok || !json.checkoutUrl) {
