'use client'

import { useEffect, useState } from 'react'
import { Loader2, CheckCircle2 } from 'lucide-react'

interface DepositConfirmationPollerProps {
  bookingToken: string
  /** Called when deposit_paid flips to true within polling window */
  onConfirmed?: () => void
}

type PollState = 'polling' | 'confirmed' | 'timeout'

export function DepositConfirmationPoller({ bookingToken, onConfirmed }: DepositConfirmationPollerProps) {
  const [state, setState] = useState<PollState>('polling')

  useEffect(() => {
    let attempts = 0
    const maxAttempts = 5 // 5 × 2s = 10s max

    const interval = setInterval(async () => {
      attempts++

      try {
        const res = await fetch(`/api/public/bookings/${bookingToken}`)
        if (res.ok) {
          const json = await res.json() as { deposit_paid?: boolean }
          if (json.deposit_paid) {
            clearInterval(interval)
            setState('confirmed')
            onConfirmed?.()
            return
          }
        }
      } catch {
        // Ignore network errors during polling — not critical
      }

      if (attempts >= maxAttempts) {
        clearInterval(interval)
        setState('timeout')
      }
    }, 2000)

    return () => clearInterval(interval)
  }, [bookingToken, onConfirmed])

  if (state === 'confirmed') {
    return (
      <div className="flex items-center gap-2 text-[oklch(65%_0.14_145)]">
        <CheckCircle2 className="h-4 w-4" />
        <span className="text-sm font-medium">Deposit confirmed</span>
      </div>
    )
  }

  if (state === 'timeout') {
    return (
      <p className="text-sm text-muted-foreground">
        Payment received — your deposit will be confirmed shortly.
      </p>
    )
  }

  return (
    <div className="flex items-center gap-2 text-muted-foreground" style={{ animation: 'deposit-pulse 1.5s ease-in-out infinite' }}>
      <Loader2 className="h-4 w-4 animate-spin" />
      <span className="text-sm">Confirming payment...</span>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { StudioSubscriptionRpcSchema, BillingSummaryRpcSchema } from '@/lib/billing/schemas'
import { BillingPageClient } from './BillingPageClient'
import { Skeleton } from '@/components/ui/skeleton'
import { Suspense } from 'react'

export const metadata: Metadata = {
  title: 'Billing & Plan — InkOS',
}

async function BillingContent() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // Fetch all billing data in parallel
  const [subRpc, summaryRpc, plansResult, invoicesResult] = await Promise.all([
    supabase.rpc('get_studio_subscription', { p_studio_id: auth.studioId }),
    supabase.rpc('get_billing_summary', { p_studio_id: auth.studioId }),
    supabase
      .from('plans')
      .select('id, tier, billing_cycle, display_name, price_cents, currency, max_artists, max_locations, sms_monthly_quota, ai_generations_quota, features, sort_order')
      .eq('is_active', true)
      .order('sort_order', { ascending: true }),
    supabase
      .from('invoices')
      .select('id, dodo_invoice_id, amount_cents, tax_cents, currency, status, period_start, period_end, paid_at, due_date, pdf_url, hosted_url, created_at')
      .eq('studio_id', auth.studioId)
      .order('created_at', { ascending: false })
      .limit(20),
  ])

  const subscriptionParsed = StudioSubscriptionRpcSchema.safeParse(subRpc.data)
  const summaryParsed = BillingSummaryRpcSchema.safeParse(summaryRpc.data)

  if (!subscriptionParsed.success || !summaryParsed.success) {
    // Subscription row may not exist yet for brand-new studios
    return (
      <div className="p-6 max-w-5xl space-y-8">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Billing &amp; Plan</h1>
          <p className="mt-1 text-sm text-muted-foreground">Set up billing to access all InkOS features.</p>
        </div>
        <BillingPageClient
          subscription={null}
          plans={plansResult.data ?? []}
          usage={{}}
          invoices={invoicesResult.data ?? []}
          isOwner={auth.role === 'owner'}
        />
      </div>
    )
  }

  return (
    <div className="p-6 max-w-5xl space-y-8">
      <div>
        <h1 className="text-2xl font-semibold tracking-tight">Billing &amp; Plan</h1>
        <p className="mt-1 text-sm text-muted-foreground">Manage your subscription and usage.</p>
      </div>
      <BillingPageClient
        subscription={subscriptionParsed.data.subscription}
        plan={subscriptionParsed.data.plan}
        plans={plansResult.data ?? []}
        usage={summaryParsed.data.current_usage}
        invoices={invoicesResult.data ?? []}
        isOwner={auth.role === 'owner'}
      />
    </div>
  )
}

export default function Page() {
  return (
    <Suspense
      fallback={
        <div className="p-6 max-w-5xl space-y-8">
