'use client'

import { useEffect, useState } from 'react'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { MrrCard } from '@/components/admin/billing/MrrCard'
import { SubscriptionList } from '@/components/admin/billing/SubscriptionList'
import { WebhookLogTable } from '@/components/admin/billing/WebhookLogTable'
import { FailedPaymentsList } from '@/components/admin/billing/FailedPaymentsList'
import { Skeleton } from '@/components/ui/skeleton'

interface OverviewData {
  mrrCents: number
  activeCount: number
  trialCount: number
  pastDueCount: number
  cancelledLast30dCount: number
  planBreakdown: Record<string, number>
}

interface SubsResponse {
  subscriptions: Parameters<typeof SubscriptionList>[0]['subscriptions']
  total: number
}

interface WebhooksResponse {
  events: Parameters<typeof WebhookLogTable>[0]['events']
  total: number
}

interface FailedPaymentsResponse {
  payments: Parameters<typeof FailedPaymentsList>[0]['payments']
  total: number
}

const LIMIT = 25

export function AdminBillingClient() {
  const [overview, setOverview] = useState<OverviewData | null>(null)
  const [subs, setSubs] = useState<SubsResponse>({ subscriptions: [], total: 0 })
  const [webhooks, setWebhooks] = useState<WebhooksResponse>({ events: [], total: 0 })
  const [failedPayments, setFailedPayments] = useState<FailedPaymentsResponse>({ payments: [], total: 0 })

  const [subsPage, setSubsPage] = useState(1)
  const [webhooksPage, setWebhooksPage] = useState(1)
  const [failedPage, setFailedPage] = useState(1)

  const [loadingOverview, setLoadingOverview] = useState(true)
  const [loadingSubs, setLoadingSubs] = useState(true)
  const [loadingWebhooks, setLoadingWebhooks] = useState(false)
  const [loadingFailed, setLoadingFailed] = useState(false)

  useEffect(() => {
    setLoadingOverview(true)
    fetch('/api/admin/billing/overview')
      .then((r) => r.json())
      .then((d: OverviewData) => setOverview(d))
      .catch(() => undefined)
      .finally(() => setLoadingOverview(false))
  }, [])

  useEffect(() => {
    setLoadingSubs(true)
    fetch(`/api/admin/billing/subscriptions?page=${subsPage}&limit=${LIMIT}`)
      .then((r) => r.json())
      .then((d: SubsResponse) => setSubs(d))
      .catch(() => undefined)
      .finally(() => setLoadingSubs(false))
  }, [subsPage])

  function loadWebhooks(page: number) {
    setLoadingWebhooks(true)
    fetch(`/api/admin/billing/webhooks?page=${page}&limit=${LIMIT}`)
      .then((r) => r.json())
      .then((d: WebhooksResponse) => setWebhooks(d))
      .catch(() => undefined)
      .finally(() => setLoadingWebhooks(false))
  }

  function loadFailedPayments(page: number) {
    setLoadingFailed(true)
    fetch(`/api/admin/billing/failed-payments?page=${page}&limit=${LIMIT}`)
      .then((r) => r.json())
      .then((d: FailedPaymentsResponse) => setFailedPayments(d))
      .catch(() => undefined)
      .finally(() => setLoadingFailed(false))
  }

  return (
    <div className="p-6 max-w-7xl space-y-8">
      <div>
        <h1 className="text-2xl font-semibold tracking-tight">Billing</h1>
        <p className="mt-1 text-sm text-muted-foreground">Platform billing overview and subscription management.</p>
      </div>

      {/* MRR overview cards */}
      {loadingOverview ? (
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-28 rounded-xl" />)}
        </div>
      ) : overview ? (
        <MrrCard data={overview} />
      ) : null}

      <Tabs defaultValue="subscriptions">
        <TabsList>
          <TabsTrigger value="subscriptions">Subscriptions</TabsTrigger>
          <TabsTrigger value="webhooks" onClick={() => loadWebhooks(webhooksPage)}>
            Webhooks
          </TabsTrigger>
          <TabsTrigger value="failed" onClick={() => loadFailedPayments(failedPage)}>
            Failed Payments
          </TabsTrigger>
        </TabsList>

        <TabsContent value="subscriptions" className="mt-4">
          <SubscriptionList
            subscriptions={subs.subscriptions}
            total={subs.total}
            page={subsPage}
            limit={LIMIT}
            onPageChange={(p) => setSubsPage(p)}
            isLoading={loadingSubs}
          />
        </TabsContent>

        <TabsContent value="webhooks" className="mt-4">
          <WebhookLogTable
            events={webhooks.events}
            total={webhooks.total}
            page={webhooksPage}
            limit={LIMIT}
            onPageChange={(p) => { setWebhooksPage(p); loadWebhooks(p) }}
            isLoading={loadingWebhooks}
          />
        </TabsContent>

        <TabsContent value="failed" className="mt-4">
          <FailedPaymentsList
            payments={failedPayments.payments}
            total={failedPayments.total}
            page={failedPage}
            limit={LIMIT}
            onPageChange={(p) => { setFailedPage(p); loadFailedPayments(p) }}
            isLoading={loadingFailed}
          />
        </TabsContent>
      </Tabs>
    </div>
  )
}

