import { dodo } from './client'

export interface CreateCheckoutParams {
  productId: string
  customerId?: string
  returnUrl: string
  metadata?: Record<string, string>
  quantity?: number
}

export interface CheckoutResult {
  checkoutUrl: string
  checkoutId: string
}

/**
 * Creates a Dodo Payments subscription checkout and returns the redirect URL.
 * Never build a card form — always redirect to Dodo hosted checkout.
 *
 * Uses `dodo.subscriptions.create` with `payment_link: true` + `return_url`.
 * The `billing` field is required by the Dodo SDK; we pass a minimal placeholder
 * that Dodo allows the customer to fill in during checkout (country is required
 * but the value passed here can be overridden at checkout).
 */
export async function createCheckoutSession(params: CreateCheckoutParams): Promise<CheckoutResult> {
  const customer = params.customerId
    ? { customer_id: params.customerId }
    : { create: false as const, email: '' }

  const session = await dodo.subscriptions.create({
    product_id: params.productId,
    customer: customer as Parameters<typeof dodo.subscriptions.create>[0]['customer'],
    billing: { country: 'US' },
    quantity: params.quantity ?? 1,
    payment_link: true,
    return_url: params.returnUrl,
    metadata: params.metadata ?? {},
  })

  const raw = session as { payment_link?: string; url?: string; id?: string }
  return {
    checkoutUrl: raw.payment_link ?? raw.url ?? '',
    checkoutId: raw.id ?? '',
  }
}

/**
 * Creates a one-time payment checkout (for deposits / balance collection).
 * Uses `dodo.payments.create` with `payment_link: true` + `return_url`.
 */
export interface CreatePaymentCheckoutParams {
  productId: string
  amountCents: number
  currency: string
  customerId?: string
  customerEmail?: string
  returnUrl: string
  metadata?: Record<string, string>
  description?: string
}

export async function createPaymentCheckout(params: CreatePaymentCheckoutParams): Promise<CheckoutResult> {
  const customer = params.customerId
    ? { customer_id: params.customerId }
    : { create: false as const, email: params.customerEmail ?? '' }

  const session = await dodo.payments.create({
    product_cart: [{ product_id: params.productId, quantity: 1 }],
    customer: customer as Parameters<typeof dodo.payments.create>[0]['customer'],
    billing: { country: 'US' },
    payment_link: true,
    return_url: params.returnUrl,
    metadata: params.metadata ?? {},
  })

  const raw = session as { payment_link?: string; url?: string; id?: string }
  return {
    checkoutUrl: raw.payment_link ?? raw.url ?? '',
    checkoutId: raw.id ?? '',
  }
}

